import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String inputStr = scanner.next();
        int length = inputStr.length();
        StringBuilder resultStr = new StringBuilder();
        boolean foundAt = false;

        // Check if '@' exists in the string
        for (int i = 0; i < length; i++) {
            if (inputStr.charAt(i) == '@') {
                foundAt = true;
                break;
            }
        }

        char[] strChars = inputStr.toCharArray();

        for (int i = 0; i < length; i++) {
            if (i + 2 < length && strChars[i] == 'd' && strChars[i + 1] == 'o' && strChars[i + 2] == 't' && i != 0 && i != length - 3) {
                resultStr.append('.');
                strChars[i] = ' ';
                strChars[i + 1] = ' ';
                strChars[i + 2] = ' ';
            }
            if (i + 1 < length && strChars[i] == 'a' && strChars[i + 1] == 't' && i != 0 && i != length - 2 && !foundAt) {
                resultStr.append('@');
                strChars[i] = ' ';
                strChars[i + 1] = ' ';
                foundAt = true;
            } else if (strChars[i] != ' ') {
                resultStr.append(strChars[i]);
            }
        }
        System.out.println(resultStr.toString());
    }
}
